INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101123, 5, 'for', '047cbe92-c3ce-55af-8df7-5158dcf2abe9', 'Directors mix sound and light for a dark room and your full attention, then one text message nukes everyone''s night vision for the rest of the scene. Filmmakers like Christopher Nolan keep shooting on film and begging audiences to see movies in actual theaters; the least we can do is watch them there instead of through a second screen. A default phone-free policy with opt-out screenings is the compromise that respects both the art and the anxious parent: most showings stay sacred, a few stay connected. Cinemas tried being everything to everyone and got outcompeted by the couch. Time to be the one place the phone does not follow you. Venues already do this at scale: [comedians like Dave Chappelle lock phones in Yondr pouches for entire tours](https://www.mic.com/articles/129718/dave-chappelle-has-created-a-no-phone-zone-for-his-performances-here-s-how), and audiences keep coming back.', 21, '2026-09-24 00:28:04+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101124, 5, 'against', '44d149b1-751d-5761-9958-9d40b4c990c2', 'I am the customer theaters claim to want back: a mom who pays for the sitter, the tickets, and the popcorn. But I am also the emergency contact, and my sitter reaches me by phone. Lock my phone in a pouch for two and a half hours and I am not buying the ticket; I am staying home where the baby monitor works. On-call nurses, single parents, anyone waiting on a call about an aging parent, we all do the same math. A default that treats every customer like a teenager sneaking texts will quietly filter out the adults with the most disposable income. Make some screenings phone-free and I will happily pick those. Make all of them phone-free and you will never see me. The venue policies themselves admit the friction: [Yondr''s own FAQ](https://www.313presents.com/assets/doc/YONDR_FAQ-85b7c63b07.pdf) has a whole section for guests who are on call or waiting on the babysitter, because even they know the pouch is a dealbreaker for those customers.', 12, '2026-09-23 17:47:13+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101125, 5, 'against', 'd91d5f6f-1a9e-5dfb-97fa-e3a0e5c6cd1a', 'My phone is a medical device. My continuous glucose monitor sends low-blood-sugar alerts to it, and during a two-hour movie those alerts are the difference between a good night and a medical emergency. Other people rely on phones for captioning apps and assistive listening in theaters whose built-in devices are broken, filthy, or simply missing. A default pouch policy forces disabled and chronically ill customers to out themselves at the door and beg for an exception, every single time. Inclusion should not require a permission slip. Keep phone-free as an option for those who want it, but the default has to assume some of us need our screens to participate safely. Regulators take the alert function seriously: [NICE''s technology guidance on Dexcom](https://www.nice.org.uk/advice/mib233/chapter/The-technology) describes urgent-low alerts that cannot be deactivated, because for some users the phone alert is the safety device.', 18, '2026-09-24 02:41:37+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101126, 5, 'against', '40f4dfb7-5e83-5662-bc73-a3bc513529c6', 'Theaters are in no position to add friction. Domestic box office was about $9 billion in 2023 versus $11.4 billion in 2019, and the audience that drifted to streaming is exactly the casual viewer a pouch policy would annoy first. Enforcement is the other problem: ushers already deal with enough, and every confrontation over a glowing screen is a one-star review and a lost regular. Alamo Drafthouse makes strictness work because it is their whole identity; a generic multiplex copying the policy gets the complaints without the brand loyalty. The market already solved this: strict theaters exist for people who want them. A mandated default just shrinks the tent. The tent is already shrinking: [2023''s domestic box office finished at $9.05 billion](https://www.thewrap.com/2023-box-office-in-review-a-year-where-filmmakers-flourished-and-franchises-failed/), still 20% below 2019''s $11.3 billion, so adding friction for the casual moviegoer is the wrong bet.', 15, '2026-09-23 23:37:27+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101127, 25, 'for', '459f6151-07cd-5131-9c93-abc4a8b14c09', 'My players can name three sportsbooks and cannot name their state senator. These ads run during the games kids watch with their families, and they sell betting as part of fandom itself: same-screen odds, celebrity cameos, ''risk-free'' bets that are nothing of the kind. Since the 2018 Supreme Court decision opened legal betting nationwide, calls to the national problem-gambling helpline have climbed, and counselors keep saying the same thing, that the ads reach people before the harm does ([helpline](https://www.ncpgambling.org/help-treatment/national-helpline/)). We banned tobacco ads from TV because kids were watching. A whistle-to-whistle ban during live games is the same principle with fifty years of precedent.', 19, '2026-09-24 13:17:48+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101128, 25, 'for', 'bfd8c31c-2fa2-5dab-b7f1-60a5b5e4ff41', 'I counsel gamblers, and nearly every relapse story starts with a trigger: a phone buzz, a bad beat, or an ad in the fourth quarter promising a second chance. Britain tried the moderate version in 2019, a voluntary [whistle-to-whistle ban](https://bettingandgamingcouncil.com) on TV betting ads around live sport, and the industry''s own review found children''s exposure to those ads fell sharply. That tells you the ads were reaching kids in the first place. Nobody is proposing to ban betting. We are proposing to stop piping it into living rooms at full volume during the family event of the week.', 15, '2026-09-24 11:23:41+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101129, 25, 'for', '86ecb3a7-e7be-5dfb-826b-8ca03c33b037', 'Follow the money and the ban argues itself. Networks take gambling ad dollars, then the same networks'' pregame shows quote the odds, a closed loop that turns the broadcast into a sportsbook commercial with kickoffs in between. Legal wagering handle hit roughly $120 billion in 2023, per the [American Gaming Association](https://www.americangaming.org), so the industry can afford to find customers without owning the family time slot. And the public pays twice: once in the ads, again in the addiction treatment and bankruptcies that tax-funded programs absorb. Ban the ads from live broadcasts, let the books advertise everywhere else adults actually choose to look, and keep the game a game.', 18, '2026-09-24 10:04:33+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101130, 25, 'against', '14ea9e84-4082-597d-8c32-9d01294a4641', 'I own a sports bar, and I watch what actually fills seats: regulars who bet ten dollars on their team and stay for wings and three more rounds. Those customers exist because betting ads brought them into a legal, regulated market instead of an offshore site or a bookie. Push the ads off TV and the demand does not vanish; it migrates to the gray market, where nobody checks IDs, nobody funds treatment, and nobody pays state taxes. My state earmarks betting tax revenue for schools and problem-gambling programs. Kill the legal funnel and you starve the very programs the ban''s supporters say they care about. And the legal funnel is huge: [Nielsen found sportsbooks spent $1.1 billion on ads in 2023](https://www.gamingtoday.com/news/sports-betting-operators-cut-ad-spending-21-percent-2023/), money that flows through regulated channels that generate state tax revenue.', 26, '2026-09-24 12:57:04+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101131, 25, 'against', 'b0c20062-1833-5d32-98aa-1bb6fa5ed8e1', 'Someone has to pay for the games being on TV. The NFL''s media deals are worth well over $100 billion, and networks recoup that through advertising, with sportsbooks now among the biggest buyers. Ban the category and the money comes from somewhere: higher cable bills, more games behind extra paywalls, or thinner production. Fans already complain about blackouts and streaming fragmentation; making broadcasts more expensive to produce helps nobody. The honest trade is this: adults seeing ads for a legal product, or adults paying more to watch football. I will take the ads. The deals are staggering: [the NFL finalized media rights worth $10 billion a year](https://www.sportsbusinessjournal.com/Daily/Closing-Bell/2021/03/18/NFL-rights/), $110 billion over 11 years, and that money has to come from somewhere.', 15, '2026-09-24 12:37:49+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101132, 25, 'against', '6b9fdf96-46bf-5cd0-8778-e9250866cd2b', 'I am 38, I bet $25 most Sundays, I set a weekly limit in the app, and I have never missed a bill. A broadcast ban treats me like a child because some other adult cannot stop. We do not ban beer commercials because alcoholics exist; we fund treatment and require ''drink responsibly'' tags. Do the same here: mandatory deposit limits, real funding for the helpline, honest odds in the ads. Prohibition by timeslot tells adults the government trusts them to vote and serve on juries but not to see a commercial. That is not protection, it is condescension. The tools already exist: [regulators require limit-setting features](https://www.legalsportsreport.com/responsible-gambling/) like deposit, wager, and session-time limits at licensed sportsbooks. Use those; do not ban the ad slot.', 8, '2026-09-24 10:55:05+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101133, 26, 'for', '596ca794-49f2-5f0c-bab9-1733bb043efa', 'I work four tens in a hospital, and I am here to say the five-day office week is a habit, not a law of physics. The UK trial put 61 companies and nearly 3,000 workers on reduced hours for full pay, and the results embarrassed the skeptics: sick days fell by roughly two-thirds, burnout dropped, and most companies kept the schedule after the trial ended ([results](https://www.4dayweek.com)). Iceland ran the larger experiment years earlier with 2,500 public workers and found well-being rose while services held steady ([Autonomy](https://autonomy.work)). We automated half the paperwork of 1990 and gave workers none of the dividend. A four-day week just collects it.', 23, '2026-09-24 11:09:52+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101134, 26, 'for', 'a1b24302-b665-5eae-b52b-82b82b17577a', 'I run a 14-person marketing firm and we went to four days in 2023. Here is what the think pieces miss: hiring got easier overnight. Candidates pick us over bigger salaries because of Fridays, and turnover fell to nearly zero, which saves me far more than one day of output ever cost. We protect the schedule the boring way: meetings get agendas, Fridays are truly off, and client deadlines did not move. Revenue is up, not down. The five-day week assumes attention is infinite. It is not, and every owner pretending otherwise is paying for it in churn. The data backs it up: [4 Day Week Global''s pilot results](https://gpa.net/blogs/global/global-findings-from-four-day-work-week-pilot) showed revenue up across participating companies alongside drops in stress, fatigue, and resignations.', 17, '2026-09-24 12:34:52+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101135, 26, 'for', 'f92083ca-72b7-5231-9c96-9d36d67345bb', 'The strongest result from the UK trial was not revenue, it was who did the dishes. Researchers found men on the four-day schedule spent significantly more time on childcare and housework, the kind of gender-equity gain that decades of corporate pledges never delivered. My daughter''s daycare pickup stopped being a negotiation the week my company piloted Fridays off. Critics call this a perk for laptop workers, and they are half right, which is why the policy conversation should be about overtime rules and staffing, not about denying office workers a proven improvement. A shorter week does not just rest people. It redistributes life. The UK trial measured it: [men spent 27% more time on childcare](https://www.popsci.com/health/four-day-work-week-study-uk/) during the trial, a real shift in who does the care work.', 20, '2026-09-24 12:32:54+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101136, 26, 'against', 'b031140b-1c47-5dd2-8960-049a236b7026', 'My school district tried a four-day week and parents hated it. Not the idea, the logistics: Fridays became a childcare scramble for every family without a flexible job or a grandparent nearby, which is most of my classroom. The research on student outcomes is mixed at best, and shorter weeks often mean longer days that exhaust younger kids. Office trials do not translate to schools, hospitals, or anyone whose job is covering other human beings. A national push for four days would hand affluent knowledge workers a benefit while quietly taxing working parents. Fix staffing and pay first; the calendar is not the crisis. The research backs the logistics worry: [Oregon State''s Paul Thompson found math and reading performance dropped](https://berkeleyhighjacket.com/2023/opinion/four-day-school-weeks-are-not-practical/) in non-rural schools on four-day weeks, alongside spikes in absenteeism.', 24, '2026-09-24 11:22:25+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101137, 26, 'against', 'e5aeb3fe-539d-5c93-88fe-1c0b6e721c18', 'I own a restaurant. My staff cannot serve Friday dinner in four days, and I cannot pay five days of wages for four days of covers without raising prices my customers cannot absorb. The famous trials share a flaw: companies volunteered, which means the ones who suspected it would work signed up, and researchers measured the honeymoon period. Nobody ran a randomized trial on a diner, a daycare, or a plumbing company. Until someone shows this working for businesses that cannot compress hours or go remote, ''the standard workweek'' is a slogan for about a third of the economy, and the rest of us get the lecture. The margins are brutal: [the National Restaurant Association found](https://restaurant.org/research-and-media/research/restaurant-economic-insights/analysis-commentary/elevated-labor-costs-had-a-significant-impact-on-restaurant-profitability-in-2024/) full-service operators spent a median 36.5% of sales on labor in 2024, and those who let it run higher were far more likely to lose money.', 25, '2026-09-24 10:00:00+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101138, 26, 'against', 'e6a23fba-79f2-59a4-8ed9-64b6f018629c', 'I spent forty years watching management fads, and this one has the classic tells: self-selected participants, short timelines, and outcomes measured by the same consultants selling the idea. The UK trial ran six months; nobody knows what happens in year three when competitors who kept five days pull ahead. Microsoft Japan''s famous 40% productivity jump in 2019 lasted one month, in August, when half the country is on holiday anyway. I am not against rest. I am against declaring victory from a pilot and legislating it. Let companies experiment, publish honest five-year data, and then we will talk about standards. Even sympathetic reviewers agree on the gap: [What Works Wellbeing''s review](https://whatworkswellbeing.org/blog/findings-from-four-day-work-week-trial/) notes the trial had no real counterfactual, since participants volunteered and were compared only to their past selves.', 16, '2026-09-24 11:05:42+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101139, 11, 'for', 'd87fd09c-037b-501c-9b23-db48d64be33e', 'I spent three years writing headlines for a living, and I can tell you outrage is not an accident, it is inventory. The accounts that farm it post forty times a day because every furious share pays the same as a thoughtful one. The [Facebook Files reporting](https://www.wsj.com/articles/the-facebook-files-11631713039) showed the company''s own researchers found its systems rewarded divisive content, which means the platforms built the slot machine and now act surprised that people pull the lever. A share-pause will not fix the business model, but it raises the cost of the cheapest trick in the book: post first, verify never. Friction targets the supply chain, not the speaker.', 4, '2026-09-23 13:29:14+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101140, 11, 'against', 'eecf944f-ee77-5e92-a69d-1ecd87ec9f47', 'I run a small-town news site, and my most-shared posts are exactly what your filter would call outrage: a missing teenager, a boil-water notice, a factory closing that puts 200 neighbors out of work. Those posts are emotional because the events are emotional, and a pop-up asking ''are you sure?'' injects doubt into urgent community information. Meanwhile the actual rage-bait farms, with their bot networks and engagement pods, will test their way around any prompt within a week. We have watched this movie with spam filters: the professionals adapt, and the collateral damage lands on the local publisher with no compliance department. With [news deserts](https://localnewsinitiative.northwestern.edu/research/state-of-local-news/) spreading, community journalism does not need another algorithmic speed bump.', 9, '2026-09-23 16:30:48+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101141, 12, 'for', '0f1121a7-8c4b-5bc6-a6ae-cbe94e4ea1a6', 'Nobody taught me any of this and I paid for it at nineteen, doomscrolling through everyone else''s highlight reel my first semester until my sleep and my grades both cratered. What finally helped was not a lecture, it was a psych elective where we tracked our own usage for two weeks and designed personal rules, like no phone in the bedroom. Schools already do versions of this for nutrition and driver''s ed because teenagers are bad at long-term thinking; that is developmental science, not nannying. Nearly half of teens say they are online [almost constantly](https://www.pewresearch.org/internet/2022/08/10/teens-social-media-and-technology-2022/), and we hand them the device with zero instruction. A practical habits class is the least we owe them.', 9, '2026-09-23 15:15:48+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101142, 12, 'against', 'ace1be90-d574-5cee-8335-0f95f8b90978', 'I teach juniors, and I promise you a state-mandated ''healthy social media'' curriculum becomes a political football by October. One parent''s ''managing comparison culture'' is another parent''s ''the school shaming my daughter''s modeling account.'' We already watch this fight play out over library books and health class; adding a unit where teachers grade students'' relationship with their phones hands every school board a new battlefield. And the evidence that classroom lessons change teen phone habits is thin, because the behavior is driven by peers, not pamphlets. Give counselors more hours and let families handle values. The classroom cannot fix what the cafeteria rewards. It is already happening with other curricula: [school boards have become culture-war battlegrounds](https://www.usatoday.com/story/opinion/columnist/2026/08/21/florida-election-sarasota-schools-democrats-moms-liberty/91389496007/) where debates over books and lessons escalate into ideological fights.', 23, '2026-09-24 02:26:05+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101143, 13, 'for', '4025d5d0-88d0-55e8-817c-79164825f340', 'I work pediatrics, and the pattern is unmistakable: the kids who sleep badly are the kids whose whole house glows until midnight. Teenagers need eight to ten hours, and evening screen light pushes melatonin later while the group chat keeps the brain buzzing, a combination the [Sleep Foundation](https://www.sleepfoundation.org/teens-and-sleep) flags as a major driver of teen sleep debt. Individual limits fail here because a kid''s willpower is competing with every notification the parents are also answering. A shared household wind-down, screens off at ten, the on-call phone waiting in the kitchen, changes the environment instead of testing the child. You cannot out-discipline a slot machine. You can unplug the room.', 6, '2026-09-23 23:00:28+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101144, 13, 'against', '291c255a-12b6-5649-bc02-6ebd4b273652', 'Shared screen-free hours assume a family that eats dinner together at six, and that is not my house. I work rotating warehouse shifts, my ex has the kids half the week, and our ''family time'' is a video call with grandma at nine or my son showing me a game clip at midnight after my shift. A rigid household blackout would kill the few connection rituals we have, because our togetherness runs through screens, not around them. Roughly [one in six US workers](https://www.bls.gov/news.release/archives/flex2_09242019.htm) is on a non-daytime schedule, and plenty more juggle gig work and caregiving. Rules built for the 9-to-5 family keep treating the rest of us as edge cases. We are not.', 21, '2026-09-23 19:58:18+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101145, 14, 'for', 'b0c20062-1833-5d32-98aa-1bb6fa5ed8e1', 'I spent thirty years in public health, and every win looked boring up close. Smoking did not fall from 42% of adults in 1965 to around 12% today because of one dramatic intervention; it fell because of quitlines, taxes, warning labels, and a million unglamorous conversations in clinics, per [CDC data](https://www.cdc.gov/tobacco/data-statistics). Digital well-being needs the same plumbing: routine screening questions, referral lists, community programs. None of it exciting, all of it cumulative. The ''too vague'' objection was raised about mental-health screening too, and now depression screening is a standard checkup question. Public health is how a society decides a problem is real. Time to decide.', 10, '2026-09-23 14:03:33+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101146, 14, 'against', '6b9fdf96-46bf-5cd0-8778-e9250866cd2b', 'I work at a county health department, and everyone should understand what ''routine public-health service'' means on the ground: a waiting list. We lost staff during COVID, our clinic runs limited hours, and our nurses already cover three programs each. Adding digital-wellness screening means either new money, which is not coming, or quietly siphoning time from vaccinations and maternal health, which is. It also assumes we know what to do with a positive screen, and for compulsive scrolling we mostly do not; there is no nicotine patch for the feed. [KFF''s reporting](https://kffhealthnews.org/public-health/us-public-health-system-underfunded-under-threat-faces-more-cuts-amid-covid-pandemic/) on the hollowed-out public-health workforce is not an argument against caring. It is an argument against assigning new missions to a system running on fumes.', 16, '2026-09-23 21:25:11+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101181, 27, 'for', '4a8f4a7e-c9c8-5980-91d6-bb07f645fc75', 'I lived through the AT&T breakup in 1984, and the fear campaign was identical: prices will rise, service will collapse, innovation will die. What actually happened was long-distance rates fell by roughly 40 percent over the next decade and a wave of competition produced the modern telecom market. Today Google controls about 90 percent of search and paid $26.3 billion in 2021 alone to stay the default on iPhones, a fact that came out in the [Justice Department''s trial](https://www.justice.gov/antitrust). When one company can buy the front door to the internet, that is not competition. The [2020 House Judiciary report](https://judiciary.house.gov) found all four giants enjoy monopoly power after a 16-month investigation. Breakups are the American remedy for exactly this situation, and they have worked before.', 10, '2026-09-24 12:19:40+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101182, 27, 'for', '06ce25a4-efd8-5581-88f7-c154d4c5c6b6', 'I run a small subscription app with four employees. Apple takes 30 percent of every dollar my customers pay, then sells its own competing service with no such tax. That is not a marketplace, it is a toll booth with a conflict of interest. The Justice Department''s [2024 lawsuit](https://www.justice.gov/antitrust) argues Apple illegally maintains its smartphone monopoly in part by degrading rival apps and accessories, and the EU''s Digital Markets Act has already forced Apple to allow alternative app stores in Europe. Developers there are shipping updates Apple would never have permitted. If a 30 percent cut enforced by a single gatekeeper is not monopoly rent, the word has no meaning. Break up the gatekeepers and the toll booths fall with them.', 24, '2026-09-24 10:05:55+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101183, 27, 'for', '3debd55c-ef91-5778-b13e-72a4ca48bd9b', 'I worked at a local newspaper that watched its ad revenue get vacuumed up by two companies. Google sits on both sides of the ad auction, running the exchange, the buying tools, and the selling tools, and taking a cut at every step. In April 2025 a federal judge ruled Google illegally monopolized online advertising technology, agreeing with the [Justice Department''s ad-tech case](https://www.justice.gov/antitrust). Studies of programmatic advertising have found publishers keep barely half of each ad dollar while intermediaries take the rest. A free press cannot survive when the company grading the auction is also bidding in it. Splitting Google''s ad business from its exchange would not kill digital advertising. It would return it to something resembling a market.', 12, '2026-09-24 12:27:12+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101184, 27, 'against', '68507eec-bbd6-5bb8-9613-7cb6e1b560c0', 'As a software engineer, I can tell you the integration people love is exactly what breakup proposals would destroy. Google Maps works inside search, Gmail, and Calendar because one company builds all of them. The Justice Department wants to force Google to sell Chrome, but Chrome''s [open-source foundation](https://www.chromium.org/) underpins most rival browsers too, including Edge and Brave. Break that apart and you do not get five healthy competitors. You get licensing fights, broken features, and a worse product for the two billion people who use it. The [2020 House report](https://judiciary.house.gov) documented real harms, but structural breakup is the bluntest possible tool. Targeted rules on self-preferencing would fix the abuse without dynamiting products that work.', 15, '2026-09-24 12:56:33+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101185, 27, 'against', '38fea548-c1e9-55cb-8386-000018da5b31', 'While Washington debates breaking up Google and Meta, Beijing is pouring state money into AI, chips, and quantum computing. America''s tech giants are among the few Western companies with the scale to compete with subsidized Chinese champions. Splitting them into smaller pieces would not create competition with China; it would create five smaller companies that each lose to one giant one. Antitrust law exists to protect consumers, and consumers currently get search, maps, video hosting, and social networking for free. Prices have not risen; they are zero. The [Pew Research Center](https://www.pewresearch.org/internet/) has found Americans are divided on whether tech companies need more regulation, not clamoring for breakups. There are real abuses to police, but weakening our own champions during a technology race is self-sabotage dressed up as reform.', 13, '2026-09-24 12:29:28+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
INSERT INTO public.cases (id, topic_id, side, author_id, body, score, created_at) VALUES (101186, 27, 'against', 'd1e61595-e39e-548a-9fda-cc5c82c37c67', 'People forget the last big breakup took over a decade of litigation and the company it targeted, IBM, was already losing its grip by the time the case ended. The Justice Department''s IBM case ran 13 years and was dropped in 1982 as without merit, after burning enormous public and private resources. Big Tech markets move far faster than courts. By the time a breakup order survives appeal, the market may have reorganized itself: search is already being disrupted by AI assistants, and TikTok came from nowhere to challenge Meta. A breakup designed for 2020''s market could land in 2030 like a museum piece. Faster tools exist. Ban the specific conduct, like default-placement payments and self-preferencing, and enforce it quickly. Structural surgery on a patient that is already changing shape is a gamble with the whole digital economy. The DOJ case against IBM is a cautionary tale in how slowly these cases move: [Stanford](https://cs.stanford.edu/people/eroberts/cs181/projects/corporate-monopolies/government_ibm.html).', 25, '2026-09-24 11:51:19+00') ON CONFLICT (id) DO UPDATE SET topic_id=EXCLUDED.topic_id, side=EXCLUDED.side, author_id=EXCLUDED.author_id, body=EXCLUDED.body, score=EXCLUDED.score, created_at=EXCLUDED.created_at;
